import sys

def is_stack_exterminable(arr):
    stack = []
    for x in arr:
        if stack and stack[-1] == x:
            stack.pop()
        else:
            stack.append(x)
    return len(stack) == 0

def count_stack_exterminable_subarrays(n, a):
    count = 0
    for i in range(n):
        for j in range(i + 1, n + 1):
            if is_stack_exterminable(a[i:j]):
                count += 1
    return count

q = int(sys.stdin.readline())
results = []
for _ in range(q):
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))
    results.append(count_stack_exterminable_subarrays(n, a))

for result in results:
    print(result)
